solution:
terraform {
  required_version = ">= 1.5"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}
# L'opérateur pessimiste ~> 5.0 autorise 5.x mais bloque 6.0 (version majeure cassante).
# Le fichier .terraform.lock.hcl, committé dans Git, fige ensuite la version EXACTE
# choisie pour que toute l'équipe et la CI installent strictement la même.
